(6723244, 1005203, 50695, '<td valign="top">I think I oversharpened this!</td>', 'I think I oversharpened this!', '2012-03-26 14:00:39.000000', NULL, 0),
(6723245, 1004772, 112739, '<td valign="top">WTG Alessandro! I agree with Doc. You do own a great talent and know how to use it well. That IS a lot of beer!</td>', 'WTG Alessandro! I agree with Doc. You do own a great talent and know how to use it well. That IS a lot of beer!', '2012-03-26 14:05:27.000000', NULL, 0),
(6723246, 1005052, 16106, '<td valign="top">It has been a goal of mine for the last two years to get the brown with a shot I like, and here you get it with a shot I love, and Ill bet you didn''t even try. For some reason when I look at this image I can taste champagne. Fizzy bright complex and faintly intoxicating.</td>', 'It has been a goal of mine for the last two years to get the brown with a shot I like, and here you get it with a shot I love, and Ill bet you didn''t even try. For some reason when I look at this image I can taste champagne. Fizzy bright complex and faintly intoxicating.', '2012-03-26 14:08:50.000000', NULL, 0),
(6723247, 1005112, 112739, '<td valign="top">To see you Rian and Alessandro on the front page together brings back sweet memories! Yes, mountains and hiking are my drug too. The POV from below makes this a great image.</td>', 'To see you Rian and Alessandro on the front page together brings back sweet memories! Yes, mountains and hiking are my drug too. The POV from below makes this a great image.', '2012-03-26 14:09:14.000000', NULL, 0),
